select giftsim.rebalance_case(id) from giftsim.cases where odds_mode = 'auto';

on conflict (id) do update set title = excluded.title, description = excluded.description, kind = excluded.kind, stat_key = excluded.stat_key, target = excluded.target, period = excluded.period, reward_stars = excluded.reward_stars, reward_keys = excluded.reward_keys, sort = excluded.sort;
